// Pelna forma
const square = (x) => {
  return x * x;
};

// Skrot: jeden parametr (bez nawiasow), jedno wyrazenie (bez klamer/return)
const double = x => x * 2;

// Zero parametrow - nawiasy WYMAGANE
const getPi = () => 3.14159;

// Wiele parametrow - nawiasy WYMAGANE
const suma = (a, b) => a + b;

const square = (x) => {
  return x * x;
};

const double = x => x * 2;
const greet = name => `Cześć, ${name}!`;
const getPi = () => 3.14159;

console.log(square(5));    // 25
console.log(double(5));    // 10
console.log(greet("Ala")); // "Cześć, Ala!"
console.log(getPi());      // 3.14159

