exercises.solution:
const potegaKwadrat = (x) => {
  return x * x;
};

console.log(potegaKwadrat(6)); // 36

const przywitaj = imie => `Czesc, ${imie}!`;
console.log(przywitaj("Kasia")); // "Czesc, Kasia!"
console.log(przywitaj("Piotr")); // "Czesc, Piotr!"

const stworzKsiazke = (tytul, autor) => ({ tytul, autor });
console.log(stworzKsiazke("Wiedzmin", "Sapkowski"));
// { tytul: 'Wiedzmin', autor: 'Sapkowski' }

const czyPelnoletni = wiek => wiek >= 18;
console.log(czyPelnoletni(15)); // false
console.log(czyPelnoletni(20)); // true

const policzVAT = (cenaNetto) => {
  const vat = cenaNetto * 0.23;
  const cenaBrutto = cenaNetto + vat;
  return { cenaNetto, vat, cenaBrutto };
};

console.log(policzVAT(100));
// { cenaNetto: 100, vat: 23, cenaBrutto: 123 }

const opiszLiczbe = (n) => {
  if (n > 0) {
    return "dodatnia";
  }
  if (n < 0) {
    return "ujemna";
  }
  return "zero";
};

console.log(opiszLiczbe(5));  // "dodatnia"
console.log(opiszLiczbe(-2)); // "ujemna"
console.log(opiszLiczbe(0));  // "zero"

const stworzMnoznik = x => y => x * y;
const razyTrzy = stworzMnoznik(3);
console.log(razyTrzy(7)); // 21

function wykonaj(fn, wartosc) {
  return fn(wartosc);
}

console.log(wykonaj(x => x * x, 6)); // 36

const stawkaVat = 0.23;
const kalkulator = {
  liczVat: (kwota) => kwota * stawkaVat
};

console.log(kalkulator.liczVat(200)); // 46

const stworzOsobe = (imie, nazwisko, wiek) => ({ imie, nazwisko, wiek });
console.log(stworzOsobe("Jan", "Kowalski", 30));
// { imie: 'Jan', nazwisko: 'Kowalski', wiek: 30 }

const sklasyfikujWiek = (wiek) => {
  if (wiek < 13) {
    return "dziecko";
  } else if (wiek < 18) {
    return "nastolatek";
  } else {
    return "dorosly";
  }
};

console.log(sklasyfikujWiek(10)); // "dziecko"
console.log(sklasyfikujWiek(15)); // "nastolatek"
console.log(sklasyfikujWiek(25)); // "dorosly"

const opiszParzystosc = n => n % 2 === 0 ? "parzysta" : "nieparzysta";
console.log(opiszParzystosc(4)); // "parzysta"
console.log(opiszParzystosc(7)); // "nieparzysta"

let porownaj = (a, b) => a === b;
console.log(porownaj(3, 3)); // true

porownaj = (a, b) => a !== b;
console.log(porownaj(3, 3)); // false

const czyDobreHaslo = haslo => haslo.length >= 8 && haslo.length <= 20;
console.log(czyDobreHaslo("krotkie")); // false
console.log(czyDobreHaslo("bezpieczneHaslo123")); // true

